  "仅展示当前任务且已经过对应领域 loader 重验的投影；不读取原始客户行，不把对话自由文本当成业务事实。缺少 Tool 原生输入 hash 时会明确标为 provenance 派生绑定摘要。": "Shows only this task's projections rechecked by the domain loader; raw customer rows are never read and conversation text is never taken as business fact. Without the tool's native input hash it is labelled as a provenance-derived binding digest.",
