  "保留首条（first）": "Keep first",
  "保管入口仅为防重复封存核对材料身份，样本不进入 Agent、普通数据登记或 Notebook；每个独立批次只允许一次评估。macOS 上封存文件只在系统隔离的评估进程内读取，仅本机网络 Notebook 和隔离插件被拒绝读取封存目录；其他系统由平台服务进程读取。可信本地运行的 Notebook、插件及同一系统账号的其他进程仍能直接读取磁盘上的封存文件。历史可用性及外部身份核验仍未知。当前封存支持 64 MiB 文件、128 MiB 解码大小、100 万行、128 列。": "The custody entry checks material identity only to prevent sealing twice; the sample never reaches the Agent, normal data registration or Notebooks, and each independent batch allows one evaluation. On macOS the sealed file is read only inside an OS-isolated evaluation process, and only loopback-only Notebooks and isolated plugins are denied the sealed folder; on other systems the platform service process reads it. Trusted-local Notebooks, plugins and other processes of the same system account can still read the sealed file on disk. Historical availability and external identity checks remain unknown. Sealing currently supports 64 MiB files, 128 MiB decoded, 1 million rows and 128 columns.",
