  "先别取消": "Don't cancel yet",
  "先明确业务语义，再计算组合风险": "Define the business meaning first, then compute portfolio risk",
  "先查看准确撤销影响并确认所列版本。": "Review the exact revocation impact and confirm the listed versions first.",
  "先校验来源、窗口和统计口径，再人工确认调度。红色结果需要另行明确处置；来源覆盖与标签成熟保留登记方声明。": "Check the source, windows and statistics first, then confirm the schedule yourself. Red results need explicit handling; source coverage and label maturity remain the registrant's statements.",
