  "先选择模型决策或纯规则决策，再选择对应的物化策略。模型决策另需认证训练产物；原始字段的请求类型和空值规则由你明确声明，不从样本类型或缺失率推定。": "Choose a model or rules-only decision first, then the materialized strategy. Model decisions also need a certified training artifact; you declare each raw field's request type and null rule, which are never inferred from sample types or missing rates.",
