  "帮我": "Help me",
  "平台不会用技术默认值代替经营目标。请提交完整目标与约束后再生成策略开发计划。": "The platform never replaces the business objective with technical defaults. Submit the full objective and constraints before generating the strategy plan.",
  "平台事件证据引用": "Platform event evidence reference",
  "平台会校验字段是否真实存在；不会用笔数代替余额，也不会猜测损失态、LGD 或预测期限。": "The platform checks that fields exist; it never uses counts for balances or guesses loss states, LGD or the horizon.",
  "平台会重开失败或未完成项；已通过项及其审计记录会保留。": "The platform reopens failed or unfinished items; passed items and their audit records are kept.",
  "平台只从你明确点名的候选开始，随后按固定目标和并列规则在硬预算内续建；不会自动选择种子、入池、应用、采纳或部署。": "The platform starts only from candidates you name, then grows within a hard budget using fixed objectives and tie rules. It never picks seeds or adds to the Pool, applies, adopts or deploys on its own.",
  "平台只把本轮用户说明、任务内确定性证据和点名的历史材料固化为项目上下文；没有的信息可明确暂缺，不会填成 0。": "The platform freezes only your notes, the task's deterministic evidence and the named historical materials as project context. Missing information stays marked as missing and is never filled with 0.",
  "平台只训练原生 Scorecard 并物化完整原始坏账概率证据；不会比较、选择、采纳或部署模型，也不会自动选择 Cutoff。": "The platform trains only a native scorecard and materializes the full raw default-probability evidence. It never compares, selects, adopts or deploys models and never picks a cutoff.",
  "平台将按顺序运行 {0} 个模型；单项失败不会中断其余模型。": "The platform runs {0} models in order; one failure does not stop the others.",
  "平台已完成只读核验；确认后才会生成并执行标签构造计划。": "The platform finished a read-only check; the label plan is generated and run only after you confirm.",
