  "平台未提供可追溯的推荐候选，已默认勾选首项；请复核后确认。": "The platform gave no traceable recommendation, so the first item is pre-selected; review and confirm.",
  "平台正在按顺序处理批次中的模型。": "The platform is processing the batch's models in order.",
  "平台自动使用 development 作为基线，并对所有可用 validation / OOT 样本生成只读 PSI 分布漂移证据。本操作不修改 Pool、不做效果验证、不创建策略，也不晋级、采纳或部署。": "The platform uses development as the baseline and produces read-only PSI drift evidence for every available validation / OOT sample. This does not change the Pool, validate performance, create a strategy, promote, adopt or deploy.",
