  "按住 Command/Ctrl 可多选；这里只能选择投影中可见的 Bin。": "Hold Command/Ctrl to pick several; only bins visible in the projection can be chosen.",
  "按住 Command/Ctrl 明确选择 2–20 个不同字段。搜索只生成组合评估证据，不会自动构建 Cross Matrix、加入 Pool、采纳或部署。": "Hold Command/Ctrl to choose 2–20 different fields. The search only produces combination evidence; it never builds a cross matrix, adds to the Pool, adopts or deploys.",
  "按住 Command/Ctrl 选择 2–50 个节点；只创建 pointer-only OR 分组，入池需后续单独请求。": "Hold Command/Ctrl to choose 2–50 nodes; this only creates a pointer-only OR group, and pooling is a separate request.",
  "按冻结包的原始字段合同输入测试数据。提交会生成持久回执；空值仅在合同允许时使用。": "Enter test data per the frozen package's raw field contract. Submitting creates a lasting receipt; use null only where the contract allows it.",
  "按冻结版本评估一次。重复请求只返回同一份结果。": "Evaluate the frozen version once. Repeated requests return the same result.",
  "按创建月份": "By month created",
  "按受信节点签名交接准确模型、策略和 Workflow 版本；接收不改变当前生产部署。模型目前支持原生二分类 LR 的完整预处理管线，其他算法明确拒绝。": "Hand over exact model, strategy and workflow versions signed by trusted nodes; receiving does not change the current production deployment. Models currently support the full preprocessing pipeline of native binary LR; other algorithms are rejected.",
  "按四个小步骤复核即可；每次选择都会保留，最后统一执行。": "Review in four small steps; every choice is kept and everything runs at the end.",
