  "按界面从上到下首命中，命中后不再继续匹配；未命中采用上方默认动作。每条规则支持“且 / 或”条件组；“且”遇到不满足、“或”遇到满足后不再求值后续条件，缺失时报错仅对实际求值的条件生效。所有案件须声明所引用字段，可明确为未知。预览只生成待审批提案；审批后可执行本地参考流程。": "Rules apply top to bottom and the first hit wins; with no hit the default action above applies. Each rule supports “and / or” groups; “and” stops at the first failure and “or” at the first match, and missing-value errors apply only to conditions actually evaluated. Every case must declare the fields used, or mark them unknown. The preview only creates a proposal to approve; after approval the local reference flow can run.",
