  "此处录入脱敏历史声明。平台登记内容及来源指纹，不能据此独立证明外部事实。金额均为最小货币单位整数；例如明确为 CNY / 2 位小数后，100 表示 1 元。时点须带明确时区；留空的可用时间保持未知。": "Enter de-identified historical statements here. The platform registers the content and source fingerprint, which do not independently prove external facts. Amounts are integers in minor currency units; with CNY / 2 decimals, 100 means 1 yuan. Times need an explicit time zone; empty availability times stay unknown.",
