  "这个任务正在执行另一步，请等它结束。": "This task is running another step. Wait for it to finish.",
  "这个任务的材料来自本地目录：把补好的文件放进该目录，再点「刷新列表」。": "This task's materials come from a local folder: put the corrected files there, then click “Refresh list”.",
  "这个入口会继续展示在任务启动页，但当前不会打开创建弹窗。": "This entry stays on the start page but does not open the create dialog yet.",
  "这些文件是当前任务的本地分析产物，不代表策略已采纳或生产环境已上线。": "These files are local analysis artifacts of this task; they do not mean the strategy is adopted or live in production.",
  "这批新特征值不值得用？": "Are these new features worth using?",
  "这是 task-scoped Pool 变更；只提交当前投影中的类型与 Entry ID，不采纳、发布或部署策略。": "This is a task-scoped Pool change; it submits only the type and entry ID from the current projection and does not adopt, publish or deploy.",
  "这是历史去重结果，请使用最新待确认步骤确认。": "This is a historical dedup result; confirm with the latest step.",
  "这是历史建模规格，请使用最新待确认步骤调整。": "This is a historical modeling spec; adjust it with the latest step.",
