  "这是历史拼接键结果，请使用最新待确认步骤。": "This is a historical join key result; use the latest step.",
  "这是历史筛选结果，请使用最新待确认步骤确认。": "This is a historical screening result; confirm with the latest step.",
  "这是历史筛选结果，请使用最新待确认步骤调整。": "This is a historical screening result; adjust it with the latest step.",
  "这是哪一类工作？选一下，我按它准备。": "What kind of work is this? Pick one and I'll prepare for it.",
  "这是哪一类工作？选一下，我按它准备。我能做数据处理、特征分析、风险分析、组合分析、模型开发、模型验证和策略开发；订票、写作这类别的事情我做不了。": "What kind of work is this? Pick one and I'll prepare for it. I can do data processing, feature analysis, risk analysis, portfolio analysis, model development, model validation and strategy development, but not unrelated things like booking tickets or writing.",
  "这是样本数据文件，不是数据字典": "This is a sample data file, not a data dictionary",
  "这是验收要求，不是标签已经成熟的声明。历史数据只能支持相应的回测或跨期结论；缺少认证口径会显示“证据不足”。": "This is an acceptance requirement, not a statement that labels are mature. Historical data supports only backtest or cross-period conclusions; without a certified definition it shows “Insufficient evidence”.",
  "这条没用/有误": "Unhelpful / wrong",
  "这次没有设置业务验收标准，所以只说明流程已跑完，不判断业务是否达标。": "No business acceptance criteria were set, so this only says the workflow finished and does not judge business targets.",
  "这里仍是 {0} 张特征表；每张表只能生成一个最终拼接方案。选择后会先重新诊断，不会立即拼接。": "There are still {0} feature tables; each produces one final join plan. Choosing re-diagnoses first and does not join yet.",
  "这里只列出已登记的冻结包。选择后会重新校验包内容，基线与挑战方案必须属于相同决策节点。": "Only registered frozen packages are listed. Choosing one rechecks its content; the baseline and challenger must share a decision point.",
  "这里只提交当前投影中的策略类型与 Entry ID，或单变量 Asset ID；Pool revision、hash、样本、目标与月份口径全部由平台重新绑定。测算不会改 Pool、采纳或部署策略。": "Only the strategy type and entry ID from the current projection, or a univariate asset ID, are submitted; the platform rebinds the Pool revision, hash, sample, target and month definition. Estimating does not change the Pool, adopt or deploy.",
  "这里按确定性目标和约束展示已评估组合，不表达最佳、冠军或平台选择；搜索不会自动构建、选择、入池或部署。": "This shows evaluated combinations by deterministic objectives and constraints; it does not name a best, champion or platform choice, and the search never builds, chooses, pools or deploys.",
