  "逐笔绑定平台事件请求引用、主体命名空间与脱敏指纹。引用必须包含任务、请求、内容指纹与原生事件合同；平台会核对方案中的事件配方、授权和当时可得信息。这里不接受手填派生特征值。": "Bind each record's platform event request reference, subject namespace and de-identified fingerprint. A reference must include the task, request, content fingerprint and native event contract; the platform checks the package's event recipe, authorization and the information available then. Hand-entered derived feature values are not accepted.",
